//! The addon folders shipped inside the program (generated by build.rs from ../addon).

include!(concat!(env!("OUT_DIR"), "/bundled_addons.rs"));

pub fn file(addon: &str, rel: &str) -> Option<&'static [u8]> {
    FILES
        .iter()
        .find(|(a, r, _)| *a == addon && *r == rel)
        .map(|(_, _, d)| *d)
}
